// UpdateMany updates multiple Depot records matching the filter.
// It advances each @fenced field that covers a column the update sets by
// one in every row it updates, and writes one the update sets itself as
// it stands (D118), so a filter on that field compares what a caller read.
func (r *DepotRepository) UpdateMany(ctx context.Context, filter *DepotFilter, update *DepotUpdate) (int, error) {
	// Build UPDATE query
	var setClauses []string
	var values []interface{}
	paramNum := 0
	if update.Name != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`"name" = $%d`, paramNum))
		values = append(values, *update.Name)
	}
	if update.Capacity != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`capacity = $%d`, paramNum))
		values = append(values, *update.Capacity)
	}
	if update.Revision != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`revision = $%d`, paramNum))
		values = append(values, *update.Revision)
	}

	// Set updated_at

	// Set updated_by

	// Each fence the update's columns advance moves on by one (D118).
	setClauses = append(setClauses, fenceBumps(depotFences, setClauses)...)

	if len(setClauses) == 0 {
		return 0, fmt.Errorf("no fields to update")
	}

	// Build WHERE clause
	whereClause := filter.buildWhereClause(&values, paramNum)
	if whereClause == "" {
		whereClause = " WHERE deleted_at IS NULL"
	} else {
		whereClause += " AND deleted_at IS NULL"
	}

	query := fmt.Sprintf(
		`UPDATE depot SET %s%s`,
		strings.Join(setClauses, ", "),
		whereClause,
	)

	// Execute query
	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, values...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, values...)
	}
	if err != nil {
		return 0, fmt.Errorf("failed to execute update: %w", err)
	}

	return int(result.RowsAffected()), nil
}

// DeleteOne soft deletes a single Depot record by ID
func (r *DepotRepository) DeleteOne(ctx context.Context, id types.IdentityUUID) error {
	if !HasUserID(ctx) {
		return ErrNoUserInContext
	}
	query := `UPDATE depot SET deleted_at = $1, revision = depot.revision + 1 WHERE id = $2 AND deleted_at IS NULL`
	queryArgs := []interface{}{time.Now(), id.ToUUID()}

	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, queryArgs...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, queryArgs...)
	}
	if err != nil {
		return fmt.Errorf("failed to delete record: %w", err)
	}

	if result.RowsAffected() == 0 {
		return ErrNotFound
	}

	return nil
}

// DeleteMany soft deletes multiple Depot records matching the filter
func (r *DepotRepository) DeleteMany(ctx context.Context, filter *DepotFilter) (int, error) {
	if !HasUserID(ctx) {
		return 0, ErrNoUserInContext
	}

	// Build WHERE clause
	values := []interface{}{time.Now()}
	whereClause := filter.buildWhereClause(&values, 1)

	if whereClause == "" {
		whereClause = " WHERE deleted_at IS NULL"
	} else {
		whereClause += " AND deleted_at IS NULL"
	}
	query := fmt.Sprintf(`UPDATE depot SET deleted_at = $1, revision = depot.revision + 1%s`, whereClause)

	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, values...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, values...)
	}
	if err != nil {
		return 0, fmt.Errorf("failed to delete records: %w", err)
	}

	return int(result.RowsAffected()), nil
}

// HardDeleteOne permanently deletes a single Depot record by ID
func (r *DepotRepository) HardDeleteOne(ctx context.Context, id types.IdentityUUID) error {
	query := `DELETE FROM depot WHERE id = $1`
	queryArgs := []interface{}{id.ToUUID()}

	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, queryArgs...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, queryArgs...)
	}
	if err != nil {
		return fmt.Errorf("failed to delete record: %w", err)
	}

	if result.RowsAffected() == 0 {
		return ErrNotFound
	}

	return nil
}
